__bsc_own_agent_state() { [ -z "${BSC_AGENT_STATE_DIR:-}" ] && return 1; local p="$1" r="${BSC_AGENT_STATE_DIR//\\//}"; r="$(printf '%s' "$r" | tr -s '/')"; r="${r%/}"; case "$p" in "$r"|"$r"/*) return 0 ;; esac; return 1; }
__bsc_read_harvestable() { [ -z "${BSC_HARVEST_ROOTS:-}" ] && return 1; local p="$1" r; while IFS= read -r r; do [ -z "$r" ] && continue; r="${r//\\//}"; r="$(printf '%s' "$r" | tr -s '/')"; r="${r%/}"; case "$p" in "$r"|"$r"/*) return 0 ;; esac; done <<< "$BSC_HARVEST_ROOTS"; return 1; }
bsc-confine() { local root="${BSC_REPO_ROOT:-}"; [ -z "$root" ] && return 0; local j fp rel tn; j="$(cat)"; fp="$(printf '%s' "$j" | __bsc_jstr 'file_path|notebook_path')"; [ -z "$fp" ] && return 0; fp="${fp//\\//}"; fp="$(printf '%s' "$fp" | tr -s '/')"; rel="${fp#"$root"/}"; rel="${rel#./}"; case "$rel" in .claude|.claude/*) __bsc_perm confine "$fp" "config-protection (.claude)"; echo "blocked: '$fp' is the session's .claude config — #1916 config-protection" >&2; return 2 ;; esac; case "$fp" in ..|../*|*/../*|*/..) __bsc_perm confine "$fp" "leaves the repo root"; echo "blocked: '$fp' leaves the repo root ($root) — #158 FS confinement" >&2; return 2 ;; esac; case "$fp" in /*|~*|[A-Za-z]:*) case "$fp" in "$root"|"$root"/*) return 0 ;; esac; if __bsc_own_agent_state "$fp"; then return 0; fi; case "$fp" in *) tn="$(printf '%s' "$j" | __bsc_jstr tool_name)"; if [ "$tn" = "Read" ] && __bsc_read_harvestable "$fp"; then return 0; fi; __bsc_perm confine "$fp" "outside the repo root"; echo "blocked: '$fp' is outside the repo root ($root) — #158 FS confinement" >&2; return 2 ;; esac ;; esac; return 0; }
